input.script:
export const meta = {
  name: 'dream200-fit-scoring',
  description: 'Score all 223 Dream-200 companies for Cozmo AI fit (batched web-check agents)',
  phases: [
    { title: 'Score', detail: '23 agents x 10 companies, quick web enrichment + tier' },
  ],
}
phase('Score')
const CONTEXT = `You are scoring target companies for Cozmo AI (YC W22), which sells AI agents that run property & casualty insurance claims end to end: answer every intake call 24/7, read documents, apply policy rules, dispatch contractors, generate line-item repair estimates from damage photos (Xactimate/Symbility compatible), write back to the system of record. Verified positioning: hellocozmo.ai "The AI Workforce for Property & Casualty".
Two sales lanes:
- LANE A (big deals, $50K-$1M+ land-and-expand): TPAs / claims-management firms / large IA-CAT adjusting firms with real claim volume and back-office cost (FNOL call centers, desk estimators at ~$100K/yr, cost-per-claim ~$500). Buyer = COO/CEO/President who owns the P&L. PE ownership or debt pressure = urgency.
- LANE B (velocity deals, $1K-$4K/month, live in ~7 days): restoration contractors and franchise networks that miss homeowner calls, need 24/7 intake, dispatch, and photo-to-estimate. Franchise HQs can roll out network-wide.
Scoring tiers: A = dream target (high volume + urgency + reachable P&L owner). B = strong fit (multi-office regional, clear pain, smaller contract). C = marginal (tiny single-metro, homeowner-direct/retail work, low insurance-claims volume, or niche specialty like textiles/electronics/art contents). X = exclude or caution (conflict of interest, owns/licenses competing claims-tech, is itself a competitor, or otherwise not a buyer). Judge honestly; do not inflate tiers.`

const results = await pipeline(
  args,
  (batch, _orig, i) => agent(`${CONTEXT}

Score each of these ${batch.length} companies. For each you may do at most ONE quick web search (or none if the provided data is sufficient) to check size/ownership/recent signals — the provided notes are from the client and are trustworthy. Return every company in the input, same names verbatim.

${JSON.stringify(batch, null, 1)}`, {
    label: `score:batch${i}`,
    phase: 'Score',
    effort: 'low',
    schema: {
      type: 'object', required: ['results'], additionalProperties: false,
      properties: { results: { type: 'array', items: {
        type: 'object',
        required: ['company','tier','lane','employees_band','urgency_signal','disqualifier','rationale'],
        additionalProperties: false,
        properties: {
          company: { type: 'string' },
          tier: { type: 'string', enum: ['A','B','C','X'] },
          lane: { type: 'string', enum: ['A','B','both','none'] },
          employees_band: { type: 'string', description: 'estimated corporate/HQ headcount band, e.g. "10-50", "200-1000", "unknown"' },
          urgency_signal: { type: 'string', description: 'PE ownership, modernization mandate, hiring signals, call-center volume — or "none seen"' },
          disqualifier: { type: 'string', description: 'conflict/competitor-tech/other reason to avoid — or "none"' },
          rationale: { type: 'string', description: 'one sentence' }
        }
      }}}
    }
  })
)
const flat = results.filter(Boolean).flatMap(r => r.results)
log(`scored ${flat.length} companies`)
return { scored: flat }

