const QUESTIONS = [
  ["Pricing", 1, "Can we quote 1 to 4 thousand dollars per month for the restoration plan in DMs, yes or no?"],
  ["Pricing", 2, "If no: is the rule never name a price, just book the call, yes or no?"],
  ["Pricing", 3, "For TPA and carrier deals, is the typical starting workflow still around 50 to 60 thousand dollars, yes or no?"],
  ["Pricing", 4, "Is the pilot paid, or free?"],
  ["Pricing", 5, "Are restoration contracts monthly or annual? And TPA contracts, monthly or annual?"],
  ["Conversion", 6, "When a prospect is warm in the DMs, should we send them to your calendar, or to the widget where the AI calls them in sixty seconds?"],
  ["Conversion", 7, "The line, spot the AI in the first ninety seconds or we do not deploy. Safe to use in DMs, yes or no?"],
  ["Proof", 8, "Can we cite two million plus production calls and ten million plus interactions, yes or no?"],
  ["Proof", 9, "Can we mention Allianz as an early partner in DMs, yes or no?"],
  ["Proof", 10, "Can we say two of the top five US restoration franchises are onboarding, yes or no?"],
  ["Proof", 11, "For the big customer, do you want the phrase, a top two player in its category, or something softer?"],
  ["Proof", 12, "The older fintech case studies on the site, like the bank support and collections numbers. Use them with P and C buyers, or hide them?"],
  ["Compliance", 13, "SOC 2 Type One: done, or in progress? And Type Two: done, or in progress?"],
  ["Compliance", 14, "Is US data residency available today, yes or no?"],
  ["Compliance", 15, "State TPA or adjuster licenses: do you hold them, need them, or are they not applicable?"],
  ["Limits", 16, "On estimates: does Cozmo write actual Xactimate or Symbility files, or carrier-ready scope language only?"],
  ["Limits", 17, "Commercial large-loss claims: in scope, or out?"],
  ["Limits", 18, "Auto claims: in scope, or out?"],
  ["Limits", 19, "Outbound sales calls for restoration clients: offered, or intake only?"],
  ["Limits", 20, "When a call escalates to a human, is that the client's own team, or does Cozmo provide humans around the clock?"],
  ["Process", 21, "The first sales meeting: always you, or can Nuha or someone else take it?"],
  ["Process", 22, "New leads: US only, or US plus Middle East?"],
  ["Process", 23, "Perils: water, fire and storm only, or all property perils?"],
  ["Rules", 24, "On our call you named a competitor, it sounded like Fatality. Please spell the company name out letter by letter."],
  ["Rules", 25, "Besides Eberl, is there anyone we must never DM? If yes, name them; if no, just say no."],
];

const INSTRUCTIONS = `You are Snowball's voice intake assistant, speaking with Alok Kumar, co-founder and CEO of Cozmo AI. Ansh from Snowball sent him this link. Your ONLY job is to collect his answers to 25 short questions that will train the LinkedIn DM reply agent Snowball is building for Cozmo.

Style: warm, fast, zero fluff. He runs 12-hour days; respect that. Speak quickly. No small talk beyond a one-line greeting. Never explain why a question matters unless he asks. Never pitch him anything.

Flow:
1. Greet once: confirm it's Alok, say this takes about eight minutes, 25 rapid-fire questions, mostly yes-no, he can say skip anytime.
2. Ask the questions ONE at a time, in order, exactly as written below. After he answers, immediately call the log_answer tool with the question number and a faithful short transcription of his answer, then move straight to the next question. A brief "got it" is enough between questions.
3. If an answer is ambiguous, restate the two options once and take whatever he says. If he answers several questions at once, log each one separately with its own log_answer call. If he says skip, log the answer as SKIPPED. If he gives extra context beyond the question, include it in the answer text; it is valuable.
4. For question 24 he must SPELL a company name letter by letter; read the letters back to confirm before logging.
5. After question 25, ask one final open question: "Anything the DM agent must never say to a prospect?" Log it as question 26.
6. Then call the finish tool with a one-paragraph summary of the most important answers, thank him, tell him Ansh gets the answers instantly, and say goodbye.

Never invent or assume an answer. Only log what he actually said. If the connection is poor, ask him to repeat rather than guessing.

THE QUESTIONS:
${QUESTIONS.map(q => `${q[1]}. (${q[0]}) ${q[2]}`).join("\n")}`;

const TOOLS = [
  {
    type: "function",
    name: "log_answer",
    description: "Log Alok's answer to one question, immediately after he gives it. Call once per question answered.",
    parameters: {
      type: "object",
      properties: {
        question_number: { type: "integer", description: "1-26" },
        question_short: { type: "string", description: "3-6 word tag of the question, e.g. 'restoration price quotable'" },
        answer: { type: "string", description: "His answer, faithfully transcribed, including any extra context he gave" },
      },
      required: ["question_number", "question_short", "answer"],
    },
  },
  {
    type: "function",
    name: "finish",
    description: "Call once after the final question is logged, with a summary of the session.",
    parameters: {
      type: "object",
      properties: {
        summary: { type: "string", description: "One paragraph: the most important answers and any red flags" },
        questions_answered: { type: "integer" },
      },
      required: ["summary", "questions_answered"],
    },
  },
];

export default async function handler(req, res) {
  if (req.method !== "POST") return res.status(405).json({ error: "POST only" });
  const models = ["gpt-realtime-2", "gpt-realtime"];
  let lastErr = null;
  for (const model of models) {
    const r = await fetch("https://api.openai.com/v1/realtime/client_secrets", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${process.env.OPENAI_API_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        expires_after: { anchor: "created_at", seconds: 1800 },
        session: {
          type: "realtime",
          model,
          instructions: INSTRUCTIONS,
          tools: TOOLS,
          tool_choice: "auto",
          audio: { output: { voice: "marin" } },
        },
      }),
    });
    const data = await r.json();
    if (r.ok) {
      const value = data.value || (data.client_secret && data.client_secret.value);
      return res.status(200).json({ value, model });
    }
