export default async function handler(req, res) {
  if (req.method !== "POST") return res.status(405).json({ error: "POST only" });
  const b = req.body || {};
  const entry = {
    session: String(b.session || "").slice(0, 64),
    type: String(b.type || "answer").slice(0, 24),
    question_number: Number(b.question_number) || null,
    question_short: String(b.question_short || "").slice(0, 200),
    answer: String(b.answer || "").slice(0, 4000),
    summary: String(b.summary || "").slice(0, 4000),
    client: "cozmo-intake-voice",
  };
  try {
    const r = await fetch(process.env.LOG_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", "X-Intake-Key": process.env.INTAKE_KEY },
      body: JSON.stringify(entry),
    });
    return res.status(r.ok ? 200 : 502).json({ ok: r.ok });
  } catch (e) {
    return res.status(502).json({ ok: false, error: String(e).slice(0, 200) });
  }
}

