async function routeTool(name, call_id, args){
  {
    const ev = {name, call_id};
    if (ev.name === 'log_answer') {
      answered++;
      $('fill').style.width = Math.min(100, Math.round(answered/TOTAL*100)) + '%';
      $('count').textContent = answered + ' of ' + TOTAL + ' answered';
      const li = document.createElement('li');
      li.innerHTML = '<b>✓ Q' + (args.question_number||'?') + '</b>' + (args.question_short||'') + ' — ' + (args.answer||'');
