    const keys = Object.keys(sessions).sort((a,b)=> (sessions[b][0].ts||'').localeCompare(sessions[a][0].ts||''));
    for (const s of keys){
      const rows = sessions[s];
      html += '<h2>' + esc(s) + ' <small style=color:#999>(' + esc((rows[0].ts||'').slice(0,16).replace('T',' ')) + ' UTC, ' + rows.filter(r=>r.type==='answer').length + ' answers)</small></h2>';
      for (const r of rows.filter(r=>r.type==='finish')) html += '<div class=sum><b>Agent summary:</b> ' + esc(r.summary) + '</div>';
      html += '<table><tr><th>#</th><th>Question</th><th>Answer</th></tr>';
      for (const r of rows.filter(r=>r.type==='answer').sort((a,b)=>(a.question_number||99)-(b.question_number||99)))
        html += '<tr><td>' + esc(r.question_number ?? '') + '</td><td>' + esc(r.question_short) + '</td><td><b>' + esc(r.answer) + '</b></td></tr>';
      html += '</table>';
    }
    res.writeHead(200, {'content-type':'text/html; charset=utf-8'});
    res.end(html);
  } else { res.writeHead(404); res.end(); }
});
server.listen(8899, '127.0.0.1', () => console.log('voice-intake logger on :8899'));
